    def search_driver(self):
        target_driver = self.driverTextEdit.text()
        self.driver = self.dbagent.get_driver_info_by_last_name(target_driver)
        if (self.driver):
            self.driverTextEdit.setText(f'{self.driver["last_name"]} {self.driver["first_name"]} {self.driver["patronymic"]}')
        else:
            self.driverTextEdit.setText("Не найдено")

    def search_car(self):
        target_car = self.carTextEdit.text()
        self.car = self.dbagent.get_car_info_by_number(target_car)
        if (self.car):
            self.carTextEdit.setText(f'{self.car["number"]} {self.car["brand"]}')
        else:
            self.carTextEdit.setText("Не найдено")

    def __show_db_drivers(self):
        dlg = DBDialog(self.dbagent, DBDialog.TableType.DRIVERS)
        dlg.exec()

    def __show_db_cars(self):
        dlg = DBDialog(self.dbagent, DBDialog.TableType.CARS)
        dlg.exec()

